import { ArrowRight } from "lucide-react";
import type { ComponentProps, ElementType, ReactNode } from "react";
import { cn } from "./lib/cn";
import { StageScope } from "./stage-scope";
import "./block-concept.css";

/**
 * Marketing blocks share one voice: monochrome from the system tokens, Geist
 * display with two-tone titles, ink actions, ruled sections and ember only for
 * focus. Blocks follow the page theme, and the Caliper UI controls inside them too.
 */

export type BlockAction = { label: string; href?: string; onClick?: () => void };

/**
 * A full-bleed band. The section is the container, so everything inside lays
 * out by the block's own width; `block-inner` holds the measure and rhythm.
 * `backdrop` paints behind the content edge to edge (grid lines, a tone).
 */
export function BlockRoot({
  as: Tag = "section",
  width = "default",
  backdrop,
  tone,
  className,
  innerClassName,
  children,
  ...props
}: Omit<ComponentProps<"section">, "ref"> & {
  /** The band's element; a site footer is a footer. */
  as?: "section" | "footer" | "div";
  /** default 1240px · narrow 960px · wide 1440px. */
  width?: "default" | "narrow" | "wide";
  backdrop?: ReactNode;
  /** A band tone: the page colour or the sunken colour. */
  tone?: "page" | "sunken" | "ink";
  innerClassName?: string;
}) {
  return (
    <Tag data-slot="block" data-tone={tone} className={cn("@container relative isolate overflow-clip", className)} {...props}>
      {backdrop}
      <div data-slot="block-inner" data-width={width} className={innerClassName}>
        {children}
      </div>
    </Tag>
  );
}

export function BlockEyebrow({ className, ...props }: ComponentProps<"p">) {
  return <p data-slot="block-eyebrow" className={className} {...props} />;
}

/** A display heading in the block face. size 1 is the hero headline. */
export function BlockTitle({
  as: Tag = "h2",
  size = 2,
  className,
  ...props
}: ComponentProps<"h2"> & { as?: "h1" | "h2" | "h3"; size?: 1 | 2 | 3 }) {
  return <Tag data-slot="block-title" data-size={size} className={className} {...props} />;
}

/** The second tone of a title: these words land in grey. */
export function BlockEm({ className, ...props }: ComponentProps<"em">) {
  return <em data-slot="block-em" className={className} {...props} />;
}

export function BlockLead({ className, ...props }: ComponentProps<"p">) {
  return <p data-slot="block-lead" className={className} {...props} />;
}

/**
 * The section opening every block shares: eyebrow, title and lead. `split`
 * sets the lead beside the title on wide blocks; `center` stacks it centred.
 */
export function BlockHeader({
  eyebrow,
  title,
  lead,
  align = "start",
  aside,
  headingLevel = 2,
  className,
}: {
  eyebrow?: ReactNode;
  title: ReactNode;
  lead?: ReactNode;
  align?: "start" | "center" | "split";
  /** 1 when the block opens the page, e.g. a pricing page. */
  headingLevel?: 1 | 2;
  /** Sits at the end of the header row, e.g. a period toggle. */
  aside?: ReactNode;
  className?: string;
}) {
  return (
    <header data-slot="block-header" data-align={align} className={className}>
      <div data-slot="block-header-title">
        {eyebrow && <BlockEyebrow>{eyebrow}</BlockEyebrow>}
        <BlockTitle as={headingLevel === 1 ? "h1" : "h2"}>{title}</BlockTitle>
      </div>
      {(lead || aside) && (
        <div data-slot="block-header-aside">
          {lead && <BlockLead>{lead}</BlockLead>}
          {aside}
        </div>
      )}
    </header>
  );
}

export function BlockActions({
  primary,
  secondary,
  className,
  block = false,
}: {
  primary?: BlockAction;
  secondary?: BlockAction;
  className?: string;
  /** Full-width actions, e.g. on phones. */
  block?: boolean;
}) {
  if (!primary && !secondary) return null;
  return (
    <div data-slot="block-actions" className={cn("flex flex-wrap gap-3", block && "@max-[520px]:grid @max-[520px]:grid-cols-1", className)}>
      {primary && <BlockButton action={primary} kind="primary" arrow />}
      {secondary && <BlockButton action={secondary} kind="secondary" />}
    </div>
  );
}

export function BlockButton({ action, kind = "primary", arrow = false, link: Link = "a" }: { action: BlockAction; kind?: "primary" | "secondary"; arrow?: boolean; /** The element for a link action, e.g. your router's Link. */ link?: ElementType }) {
  const shared = { "data-slot": "block-button", "data-kind": kind } as const;
  const content = (
    <>
      {action.label}
      {arrow && <ArrowRight aria-hidden="true" data-slot="block-button-arrow" className="size-4" />}
    </>
  );
  return action.href ? (
    <Link href={action.href} {...shared}>
      {content}
    </Link>
  ) : (
    <button type="button" onClick={action.onClick} {...shared}>
      {content}
    </button>
  );
}

export function BlockCard({ className, ...props }: ComponentProps<"div">) {
  return <div data-slot="block-card" className={className} {...props} />;
}

export function BlockChip({ className, ...props }: ComponentProps<"span">) {
  return <span data-slot="block-chip" className={className} {...props} />;
}

/**
 * A product artefact on a stage: a dotted tonal panel holding a framed window, with an optional floating note that overlaps the
 * window's corner on wide blocks and sits beneath it on narrow ones.
 */
export function BlockStage({
  title,
  floating,
  bare = false,
  className,
  children,
}: {
  /** Shown in the window bar, e.g. "halden.app/close". */
  title?: string;
  floating?: ReactNode;
  /** No window frame: the children bring their own surfaces. */
  bare?: boolean;
  className?: string;
  children: ReactNode;
}) {
  return (
    <div data-slot="block-stage" className={className}>
      {bare ? (
        <StageScope>{children}</StageScope>
      ) : (
        <div data-slot="block-window">
          <div data-slot="block-window-bar" aria-hidden={title ? undefined : true}>
            <span data-slot="block-window-dots" aria-hidden="true"><i /><i /><i /></span>
            {title && <span data-slot="block-window-title">{title}</span>}
          </div>
          <div data-slot="block-window-body"><StageScope>{children}</StageScope></div>
        </div>
      )}
      {floating && <div data-slot="block-float">{floating}</div>}
    </div>
  );
}

/** Company names set as type in a quiet row; swap in SVG marks in production. */
export function BlockLogos({ label, logos, className }: { label?: string; logos: readonly string[]; className?: string }) {
  return (
    <div data-slot="block-logos" className={className}>
      {label && <p data-slot="block-logos-label">{label}</p>}
      <ul aria-label={label ?? "Customers"}>
        {logos.map((logo) => (
          <li key={logo}>{logo}</li>
        ))}
      </ul>
    </div>
  );
}

/** Initials from a name, in the block's highlight tones. */
export function BlockInitials({ name, size = 36, tone, className }: { name: string; size?: number; tone?: number; className?: string }) {
  const words = name.trim().split(/\s+/u);
  const initials = ((words[0]?.[0] ?? "") + (words.length > 1 ? (words[words.length - 1]?.[0] ?? "") : "")).toUpperCase();
  return (
    <span data-slot="block-initials" data-tone={tone === undefined ? undefined : tone % 4} aria-hidden="true" className={className} style={{ width: size, height: size, fontSize: Math.round(size / 2.8) }}>
      {initials}
    </span>
  );
}

export type BlockStat = { value: ReactNode; label: string };

"use client";

import { Menu, X } from "lucide-react";
import { useEffect, useId, useRef, useState, type ElementType, type ReactNode } from "react";
import { BlockButton, type BlockAction } from "./block-concept";
import { cn } from "./lib/cn";
import "./shared/site-header.css";
import "./block-nav.css";

export type BlockNavLink = { label: string; href: string; current?: boolean };

/**
 * The site header page templates share. It sits on the page colour, gains a
 * hairline and frost once the page scrolls, keeps the primary action in
 * reach, and on narrow pages folds the links into a menu disclosure that
 * closes with Escape and returns focus to its button.
 */
export function BlockNav({
  brand,
  brandHref = "/",
  brandLabel,
  logo,
  nav = [],
  signIn,
  primary,
  aside,
  link: Link = "a",
  className,
}: {
  brand: string;
  brandHref?: string;
  /** The home link's accessible name when the visible brand is short, e.g. "Halden home". */
  brandLabel?: string;
  /** A mark set before the brand name; the name stays the accessible label. */
  logo?: ReactNode;
  nav?: readonly BlockNavLink[];
  signIn?: BlockAction;
  primary?: BlockAction;
  /** Extra controls before the actions, e.g. a theme switch or search. */
  aside?: ReactNode;
  /** The element for the brand and nav links, e.g. your router's Link, so moving between pages stays in the app. */
  link?: ElementType;
  className?: string;
}) {
  const id = useId();
  const sentinel = useRef<HTMLDivElement>(null);
  const menuButton = useRef<HTMLButtonElement>(null);
  const [scrolled, setScrolled] = useState(false);
  const [menu, setMenu] = useState(false);

  useEffect(() => {
    const top = sentinel.current;
    if (!top) return;
    const observer = new IntersectionObserver(([entry]) => setScrolled(!entry!.isIntersecting));
    observer.observe(top);
    return () => observer.disconnect();
  }, []);

  return (
    <>
      <div ref={sentinel} aria-hidden="true" className="absolute top-0 h-px w-px" />
      <header data-slot="site-header" data-scrolled={scrolled || undefined} className={cn("sticky top-0 z-20", className)}>
        <div data-slot="block-nav-row">
          <Link href={brandHref} aria-label={brandLabel} data-slot="block-nav-brand" className={cn(logo && "inline-flex items-center gap-2.5")}>{logo}{brand}</Link>
          {nav.length > 0 && (
            <nav aria-label="Site" className="hidden @[860px]:block">
              <ul data-slot="block-nav-list">
                {nav.map((item) => (
                  <li key={item.href}>
                    <Link href={item.href} aria-current={item.current ? "page" : undefined} data-slot="block-nav-link">{item.label}</Link>
                  </li>
                ))}
              </ul>
            </nav>
          )}
          <span className="ml-auto hidden items-center gap-2 @[860px]:flex">
            {aside}
            {signIn && <BlockButton action={signIn} kind="secondary" link={Link} />}
            {primary && <BlockButton action={primary} link={Link} />}
          </span>
          {(nav.length > 0 || signIn) && (
            <button
              ref={menuButton}
              type="button"
              aria-expanded={menu}
              aria-controls={`${id}-menu`}
              onClick={() => setMenu((open) => !open)}
              data-slot="block-button"
              data-kind="secondary"
              className="ml-auto !min-h-11 !px-4 @[860px]:hidden"
            >
              {menu ? <X aria-hidden="true" className="size-4" /> : <Menu aria-hidden="true" className="size-4" />}
              Menu
            </button>
          )}
        </div>
        <div
          id={`${id}-menu`}
          hidden={!menu}
          data-slot="site-menu"
          className="absolute inset-x-0 top-full grid gap-1 border-b border-x border-border bg-[var(--elevated-glass)] px-5 pt-2 pb-6 backdrop-blur-[20px] backdrop-saturate-[1.4] [box-shadow:var(--shadow-overlay),inset_0_1px_0_var(--edge-light)] @[860px]:hidden"
          onKeyDown={(event) => {
            if (event.key === "Escape") {
              setMenu(false);
              menuButton.current?.focus();
            }
          }}
        >
          {nav.map((item) => (
            <Link key={item.href} href={item.href} aria-current={item.current ? "page" : undefined} onClick={() => setMenu(false)} className="flex h-12 items-center border-b border-[var(--k-line)] text-[17px]">
              {item.label}
            </Link>
          ))}
          {menu && aside && <div className="mt-4 flex flex-wrap items-center gap-2">{aside}</div>}
          <span className="mt-4 grid gap-2">
            {signIn && <BlockButton action={signIn} kind="secondary" link={Link} />}
            {primary && <BlockButton action={primary} link={Link} />}
          </span>
        </div>
      </header>
    </>
  );
}

"use client";

import { Slot, Slottable } from "@radix-ui/react-slot";
import { LoaderCircle } from "lucide-react";
import {
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react";
import { cn } from "./lib/cn";
import "./shared/loading-indicator.css";
import "./button.css";

/* Colour, material and press live in button.css keyed on data-variant, so a
   consumer's utility classes still override them. Raised to press: the
   button sinks 1px into an inner shade instead of scaling. */
const variants = {
  default: "",
  secondary: "",
  ghost: "",
  destructive: "",
};

const sizes = {
  sm: "h-8 gap-1.5 rounded-full px-3 text-[13px] max-md:min-h-11 [@media(pointer:coarse)]:min-h-11",
  md: "h-[var(--control-height)] gap-2 rounded-full px-3.5 text-sm",
  lg: "h-11 gap-2 rounded-full px-[18px] text-[15px]",
  icon: "size-[var(--control-height)] rounded-full p-0",
};

export type ButtonProps = ComponentProps<"button"> & {
  variant?: keyof typeof variants;
  size?: keyof typeof sizes;
  asChild?: boolean;
  /** Shows a spinner over the label and swallows clicks while keeping focus and width. */
  loading?: boolean;
  /** Animate a meaningful label/icon change, such as saving → saved. */
  feedbackKey?: string;
};

export function Button({
  className,
  variant = "default",
  size = "md",
  asChild = false,
  loading = false,
  feedbackKey,
  disabled,
  "aria-disabled": ariaDisabled,
  children,
  onClick,
  onClickCapture,
  tabIndex,
  type = "button",
  ...props
}: ButtonProps) {
  const Component = asChild ? Slot : "button";
  const nativeDisabled = Boolean(disabled);
  const blocked =
    nativeDisabled ||
    loading ||
    ariaDisabled === true ||
    ariaDisabled === "true";

  return (
    <Component
      data-slot="button"
      data-variant={variant}
      data-size={size}
      type={asChild ? undefined : type}
      className={cn(
        "relative inline-flex shrink-0 items-center justify-center whitespace-nowrap border border-transparent font-medium tracking-[-0.006em] outline-none focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:pointer-events-none aria-disabled:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
        variants[variant],
        sizes[size],
        className,
      )}
      disabled={asChild ? undefined : nativeDisabled}
      aria-disabled={nativeDisabled || ariaDisabled ? true : undefined}
      aria-busy={loading || undefined}
      tabIndex={asChild && nativeDisabled ? -1 : tabIndex}
      {...props}
      onKeyDown={(event) => {
        if (blocked && (event.key === "Enter" || event.key === " ")) {
          event.preventDefault();
        }
        props.onKeyDown?.(event);
      }}
      onClickCapture={(event) => {
        if (blocked) {
          event.preventDefault();
          event.stopPropagation();
          return;
        }
        onClickCapture?.(event);
      }}
      onClick={onClick}
    >
      {loading && asChild && (
        <LoaderCircle data-slot="loading-indicator" aria-hidden="true" />
      )}
      {loading && !asChild && feedbackKey === undefined && (
        <span data-slot="button-busy" aria-hidden="true">
          <LoaderCircle data-slot="loading-indicator" />
        </span>
      )}
      <Slottable>
        {loading && !asChild && feedbackKey === undefined ? (
          <span data-slot="button-label" data-hidden="true">
            {children}
          </span>
        ) : feedbackKey !== undefined && !asChild ? (
          <ButtonFeedback stateKey={feedbackKey}>
            {loading && (
              <LoaderCircle data-slot="loading-indicator" aria-hidden="true" />
            )}
            {children}
          </ButtonFeedback>
        ) : (
          children
        )}
      </Slottable>
    </Component>
  );
}

function ButtonFeedback({
  stateKey,
  children,
}: {
  stateKey: string;
  children: ReactNode;
}) {
  const content = useRef<HTMLSpanElement>(null);
  const [initialKey] = useState(stateKey);
  const [width, setWidth] = useState<number>();
  useLayoutEffect(() => {
    const element = content.current;
    if (!element) return;
    const measure = () => setWidth(element.offsetWidth);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, [stateKey]);
  return (
    <span data-slot="button-feedback" style={{ width }}>
      <span
        key={stateKey}
        ref={content}
        data-slot="button-feedback-label"
        data-enter={stateKey !== initialKey}
      >
        {children}
      </span>
    </span>
  );
}

"use client";

import { ArrowRight, Check } from "lucide-react";
import { useEffect, useId, useRef, useState, type ReactNode } from "react";
import { BlockRoot } from "./block-concept";
import { cn } from "./lib/cn";
import "./footer-block.css";

export type BlockFooterColumn = { title: string; links: readonly { label: string; href: string }[] };

/** Sizes the wordmark so the name spans the band exactly, whatever its length. */
function Wordmark({ children }: { children: string }) {
  const ref = useRef<HTMLParagraphElement>(null);
  useEffect(() => {
    const node = ref.current;
    const text = node?.firstElementChild as HTMLElement | null;
    if (!node || !text) return;
    // Scale from the current size, so a fitted wordmark measures as fitted and stops.
    const fit = () => {
      // Layout width, not the drawn box: inside a scaled preview or a transformed parent the drawn box is smaller.
      const width = text.offsetWidth;
      const size = parseFloat(getComputedStyle(node).fontSize);
      if (!width || !size) return;
      const next = Math.floor((size * node.clientWidth) / width);
      if (Math.abs(next - size) >= 1) node.style.setProperty("--wordmark-size", `${next}px`);
    };
    fit();
    const observer = new ResizeObserver(() => requestAnimationFrame(fit));
    observer.observe(node);
    document.fonts?.ready.then(fit);
    return () => observer.disconnect();
  }, [children]);
  return (
    <p ref={ref} data-slot="footer-wordmark" aria-hidden="true">
      <span>{children}</span>
    </p>
  );
}

const isEmail = (value: string) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/u.test(value.trim());

/**
 * The page's last word: what the company is, where everything lives, an
 * optional newsletter that confirms in place, the legal line, and the name
 * set as a wordmark across the full width of the band.
 */
export function FooterBlock({
  brand,
  tagline,
  columns,
  newsletter,
  legal,
  status,
  wordmark = true,
  className,
}: {
  brand: string;
  tagline?: string;
  columns: readonly BlockFooterColumn[];
  /** An email sign-up. `onSubmit` may return a promise; the field confirms when it settles. */
  newsletter?: { label: string; note?: string; onSubmit?: (email: string) => void | Promise<void> };
  /** e.g. "© 2026 Halden Ltd · Privacy · Terms". */
  legal?: ReactNode;
  /** A live system status line, e.g. { label: "All systems normal", href: "https://status…" }. */
  status?: { label: string; href: string };
  /** Set the brand as a full-width wordmark at the foot. */
  wordmark?: boolean;
  className?: string;
}) {
  const id = useId();
  const [email, setEmail] = useState("");
  const [state, setState] = useState<"idle" | "invalid" | "busy" | "done">("idle");

  async function submit(event: React.FormEvent) {
    event.preventDefault();
    if (!isEmail(email)) {
      setState("invalid");
      return;
    }
    setState("busy");
    await newsletter?.onSubmit?.(email.trim());
    setState("done");
  }

  return (
    <BlockRoot as="footer" tone="sunken" className={className} innerClassName="!pb-0">
      <div data-slot="footer-block" className="grid gap-[clamp(40px,6cqi,72px)]">
        <div className="grid gap-12 @[900px]:grid-cols-[minmax(0,1fr)_minmax(0,1.6fr)]">
          <div className="grid content-start gap-6">
            <p data-slot="footer-brand">{brand}</p>
            {tagline && <p className="max-w-[36ch] text-[15px] leading-6 text-[var(--k-muted)]">{tagline}</p>}
            {newsletter &&
              (state === "done" ? (
                <p role="status" className="flex items-center gap-2 text-[15px]">
                  <Check aria-hidden="true" className="size-4 text-[var(--k-hi)]" />
                  Check {email.trim()} to confirm.
                </p>
              ) : (
                <form noValidate onSubmit={submit} className="grid max-w-[400px] gap-2">
                  <label htmlFor={`${id}-email`} className="text-sm font-medium">{newsletter.label}</label>
                  <div data-slot="footer-field" data-invalid={state === "invalid" || undefined}>
                    <input
                      id={`${id}-email`}
                      type="email"
                      autoComplete="email"
                      placeholder="you@company.com"
                      value={email}
                      aria-invalid={state === "invalid" || undefined}
                      aria-describedby={`${id}-note`}
                      onChange={(event) => {
                        setEmail(event.currentTarget.value);
                        if (state === "invalid") setState("idle");
                      }}
                    />
                    <button type="submit" disabled={state === "busy"} aria-label={state === "busy" ? "Subscribing" : "Subscribe"}>
                      <ArrowRight aria-hidden="true" className="size-4" />
                    </button>
                  </div>
                  <p id={`${id}-note`} role={state === "invalid" ? "alert" : undefined} className={cn("min-h-5 text-[13px]", state === "invalid" ? "text-[var(--k-danger)]" : "text-[var(--k-muted)]")}>
                    {state === "invalid" ? "Enter an email address like name@company.com." : newsletter.note}
                  </p>
                </form>
              ))}
          </div>
          <nav aria-label="Footer" className="grid grid-cols-2 gap-x-6 gap-y-10 @[640px]:grid-cols-[repeat(var(--cols),minmax(0,1fr))]" style={{ ["--cols" as string]: Math.min(columns.length, 4) }}>
            {columns.map((column) => (
              <div key={column.title} className="grid content-start gap-4">
                <h2 data-slot="footer-heading">{column.title}</h2>
                <ul className="grid gap-2.5">
                  {column.links.map((link) => (
                    <li key={link.label}><a href={link.href} data-slot="footer-block-link">{link.label}</a></li>
                  ))}
                </ul>
              </div>
            ))}
          </nav>
        </div>
        <div className="flex flex-wrap items-center justify-between gap-x-8 gap-y-3 border-t border-[var(--k-line-strong)] pt-6 text-[13px] text-[var(--k-muted)]">
          {legal && <div>{legal}</div>}
          {status && (
            <a href={status.href} className="inline-flex items-center gap-2 hover:text-[var(--k-ink)]">
              <i aria-hidden="true" data-slot="footer-status-dot" />
              {status.label}
            </a>
          )}
        </div>
        {wordmark && (
          <Wordmark>{brand}</Wordmark>
        )}
      </div>
    </BlockRoot>
  );
}

"use client";

import { Link2, Printer } from "lucide-react";
import type { ReactNode } from "react";
import { BlockEyebrow, BlockLead, BlockRoot, BlockTitle, type BlockAction } from "./block-concept";
import type { BlockNavLink } from "./block-nav";
import { Button } from "./button";
import { TemplateOutline, TemplatePage, useScrollSpy, type TemplateFooter } from "./template-page";
import "./shared/article-prose.css";
import "./legal-template.css";

export type LegalSection = { id: string; title: string; body: ReactNode };
export type LegalVersion = { date: string; summary: string; href?: string };

const formatDate = (iso: string) => new Intl.DateTimeFormat("en-GB", { day: "numeric", month: "long", year: "numeric", timeZone: "UTC" }).format(new Date(`${iso}T00:00:00Z`));

/**
 * A policy people can actually read: the short version first, numbered
 * sections with an outline that follows the reader, linkable clauses, the
 * dates it changed and what changed, a print layout and who to ask.
 * Built only from the Free blocks.
 */
export function LegalTemplate({
  brand,
  nav,
  signIn,
  primary,
  eyebrow = "Legal",
  title,
  lead,
  updated,
  effective,
  summary = [],
  sections,
  versions = [],
  contact,
  footer,
  className,
}: {
  brand: string;
  nav?: readonly BlockNavLink[];
  signIn?: BlockAction;
  primary?: BlockAction;
  eyebrow?: string;
  title: string;
  lead?: string;
  /** ISO date of the last change. */
  updated: string;
  /** ISO date the current text applies from, if different. */
  effective?: string;
  /** The short version, in plain sentences. */
  summary?: readonly string[];
  sections: readonly LegalSection[];
  /** Earlier versions, newest first. */
  versions?: readonly LegalVersion[];
  /** Who answers questions, e.g. { label: "privacy@halden.app", href: "mailto:privacy@halden.app" }. */
  contact?: { label: string; href: string };
  footer?: TemplateFooter;
  className?: string;
}) {
  const active = useScrollSpy(sections.map((section) => section.id));
  return (
    <TemplatePage brand={brand} nav={nav} signIn={signIn} primary={primary} footer={footer} className={className}>
      <BlockRoot width="default" as="div" innerClassName="!pb-10">
        <header data-slot="legal-header">
          <div className="grid gap-5">
            <BlockEyebrow>{eyebrow}</BlockEyebrow>
            <BlockTitle as="h1" size={2}>{title}</BlockTitle>
            {lead && <BlockLead>{lead}</BlockLead>}
          </div>
          <div data-slot="legal-dates">
            <p className="m-0">
              <span className="text-[var(--k-muted)]">Last updated </span>
              <time dateTime={updated}>{formatDate(updated)}</time>
            </p>
            {effective && (
              <p className="m-0">
                <span className="text-[var(--k-muted)]">In effect from </span>
                <time dateTime={effective}>{formatDate(effective)}</time>
              </p>
            )}
            <Button variant="secondary" size="sm" onClick={() => window.print()} data-print-hide="">
              <Printer aria-hidden="true" />
              Print or save as PDF
            </Button>
          </div>
        </header>
      </BlockRoot>
      <BlockRoot width="default" as="div" innerClassName="!pt-0">
        <div data-slot="article-layout">
          <TemplateOutline items={sections} active={active} label="Sections" numbered />
          <div data-slot="article-body">
            {summary.length > 0 && (
              <section data-slot="legal-summary" aria-labelledby="legal-summary-title">
                <h2 id="legal-summary-title" className="m-0 text-[17px] font-medium">The short version</h2>
                <ul>
                  {summary.map((line) => (
                    <li key={line}>{line}</li>
                  ))}
                </ul>
                <p className="m-0 text-[13px] text-[var(--k-muted)]">This summary helps you read the policy; the numbered sections below are what applies.</p>
              </section>
            )}
            {sections.map((section, index) => (
              <section key={section.id} id={section.id} aria-labelledby={`${section.id}-title`}>
                <h2 id={`${section.id}-title`} data-slot="article-heading">
                  <span data-slot="legal-number">{index + 1}.</span>
                  {section.title}
                  <a href={`#${section.id}`} data-slot="article-anchor" aria-label={`Link to section ${index + 1}, ${section.title}`}>
                    <Link2 aria-hidden="true" />
                  </a>
                </h2>
                <div data-slot="article-prose">{section.body}</div>
              </section>
            ))}
            {versions.length > 0 && (
              <section aria-labelledby="legal-history" data-slot="legal-history">
                <h2 id="legal-history" className="m-0 text-[17px] font-medium">Version history</h2>
                <ol>
                  {versions.map((version) => (
                    <li key={version.date}>
                      <time dateTime={version.date}>{formatDate(version.date)}</time>
                      <span>
                        {version.summary}
                        {version.href && (
                          <>
                            {" "}
                            <a href={version.href} className="underline underline-offset-4">Read that version</a>
                          </>
                        )}
                      </span>
                    </li>
                  ))}
                </ol>
              </section>
            )}
            {contact && (
              <p className="m-0 border-t border-[var(--k-line)] pt-6 text-[15px] text-[var(--k-muted)]">
                Questions about this policy? Write to <a href={contact.href} className="text-[var(--k-ink)] underline underline-offset-4">{contact.label}</a>.
              </p>
            )}
          </div>
        </div>
      </BlockRoot>
    </TemplatePage>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import { createContext, useContext, type ReactNode } from "react";

/**
 * True inside a block stage: a frame shown there is a demonstration on a page
 * that already has its own main landmark, so it should not add a second one.
 */
const InStage = createContext(false);

export function StageScope({ children }: { children: ReactNode }) {
  return <InStage.Provider value={true}>{children}</InStage.Provider>;
}

export const useInStage = () => useContext(InStage);

"use client";

import { useEffect, useId, useState, type ComponentProps, type ReactNode } from "react";
import type { BlockAction } from "./block-concept";
import { BlockNav, type BlockNavLink } from "./block-nav";
import { FooterBlock } from "./footer-block";
import { cn } from "./lib/cn";
import "./shared/skip-link.css";
import "./template-page.css";

export type TemplateFooter = Omit<ComponentProps<typeof FooterBlock>, "brand" | "className"> & { brand?: string };

/**
 * The frame every Free page template shares: a skip link, the site header,
 * one main region that can take focus, and the footer block. Pages put
 * their bands inside.
 */
export function TemplatePage({
  brand,
  nav = [],
  signIn,
  primary,
  footer,
  className,
  children,
}: {
  brand: string;
  nav?: readonly BlockNavLink[];
  signIn?: BlockAction;
  primary?: BlockAction;
  footer?: TemplateFooter;
  className?: string;
  children: ReactNode;
}) {
  const id = useId();
  return (
    <div data-slot="block" className={cn("@container relative", className)}>
      <a href={`#${id}-main`} data-slot="skip-link">Skip to content</a>
      <BlockNav brand={brand} nav={nav} signIn={signIn} primary={primary} />
      <main id={`${id}-main`} tabIndex={-1} className="outline-none">
        {children}
      </main>
      {footer && <FooterBlock {...footer} brand={footer.brand ?? brand} />}
    </div>
  );
}

/** The nearest element that scrolls, or null for the window. */
export function scrollParent(element: HTMLElement | null): HTMLElement | null {
  for (let node = element?.parentElement; node; node = node.parentElement) {
    const { overflowY } = getComputedStyle(node);
    if ((overflowY === "auto" || overflowY === "scroll") && node.scrollHeight > node.clientHeight) return node;
  }
  return null;
}

/**
 * Which section the reader is in: the last heading that has passed a line
 * just under the sticky header. Works in the window or a scrolling panel.
 */
export function useScrollSpy(ids: readonly string[], offset = 120) {
  const [active, setActive] = useState(ids[0] ?? "");
  const key = ids.join("|");
  useEffect(() => {
    const first = ids[0] ? document.getElementById(ids[0]) : null;
    if (!first) return;
    const scroller = scrollParent(first);
    const target: HTMLElement | Window = scroller ?? window;
    const update = () => {
      const top = scroller ? scroller.getBoundingClientRect().top : 0;
      let current = ids[0]!;
      for (const id of ids) {
        const element = document.getElementById(id);
        if (element && element.getBoundingClientRect().top - top <= offset) current = id;
      }
      setActive(current);
    };
    update();
    target.addEventListener("scroll", update, { passive: true });
    window.addEventListener("resize", update);
    return () => {
      target.removeEventListener("scroll", update);
      window.removeEventListener("resize", update);
    };
    // ids are compared by value through `key`.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key, offset]);
  return active;
}

/** How far through an element the reader is, 0 to 1. */
export function useReadingProgress(element: HTMLElement | null) {
  const [progress, setProgress] = useState(0);
  useEffect(() => {
    if (!element) return;
    const scroller = scrollParent(element);
    const target: HTMLElement | Window = scroller ?? window;
    const update = () => {
      const rect = element.getBoundingClientRect();
      const top = scroller ? scroller.getBoundingClientRect().top : 0;
      const view = scroller ? scroller.clientHeight : window.innerHeight;
      const travel = rect.height - view;
      setProgress(travel <= 0 ? 1 : Math.min(1, Math.max(0, (top - rect.top) / travel)));
    };
    update();
    target.addEventListener("scroll", update, { passive: true });
    window.addEventListener("resize", update);
    return () => {
      target.removeEventListener("scroll", update);
      window.removeEventListener("resize", update);
    };
  }, [element]);
  return progress;
}

/** Jumps to a section inside whatever scrolls, then moves focus to its heading. */
export function goToSection(id: string) {
  const element = document.getElementById(id);
  if (!element) return;
  const smooth = !window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  element.scrollIntoView({ behavior: smooth ? "smooth" : "auto", block: "start" });
  const heading = element.matches("h1, h2, h3") ? element : element.querySelector<HTMLElement>("h2, h3");
  heading?.setAttribute("tabindex", "-1");
  heading?.focus({ preventScroll: true });
}

/**
 * The page outline: numbered when `numbered`, with the reader's section
 * marked as current. On narrow pages it folds into a disclosure.
 */
export function TemplateOutline({
  items,
  active,
  label = "On this page",
  numbered = false,
  className,
}: {
  items: readonly { id: string; title: string }[];
  active: string;
  label?: string;
  numbered?: boolean;
  className?: string;
}) {
  const list = (
    <ol data-slot="template-outline-list" data-numbered={numbered || undefined}>
      {items.map((item, index) => (
        <li key={item.id}>
          <a
            href={`#${item.id}`}
            aria-current={active === item.id ? "location" : undefined}
            onClick={(event) => {
              event.preventDefault();
              goToSection(item.id);
              history.replaceState(null, "", `#${item.id}`);
            }}
          >
            {numbered && <span data-slot="template-outline-number">{index + 1}.</span>}
            {item.title}
          </a>
        </li>
      ))}
    </ol>
  );
  return (
    <nav aria-label={label} data-slot="template-outline" className={className}>
      <p data-slot="template-outline-label">{label}</p>
      {list}
      <details data-slot="template-outline-fold">
        <summary>{label}</summary>
        {list}
      </details>
    </nav>
  );
}

