  [data-slot="template-outline-list"] a::before { content: ""; position: absolute; left: 0; top: 6px; bottom: 6px; width: 2px; border-radius: 2px; background: var(--k-line); transition: background-color var(--duration-normal) var(--ease-out); }
  [data-slot="template-outline-list"] a:hover { color: var(--k-ink); }
  [data-slot="template-outline-list"] a[aria-current] { color: var(--k-ink); }
  [data-slot="template-outline-list"] a[aria-current]::before { background: var(--k-hi); }
  [data-slot="template-outline-list"] a:focus-visible { outline: 2px solid var(--k-focus, var(--k-hi)); outline-offset: 2px; border-radius: 4px; }
  [data-slot="template-outline-number"] { flex: none; min-width: 1.6em; font-variant-numeric: tabular-nums; }
  [data-slot="template-outline-fold"] { border-radius: var(--k-radius); background: var(--k-surface); box-shadow: 0 0 0 1px var(--k-line); }
  [data-slot="template-outline-fold"] > summary { display: flex; align-items: center; justify-content: space-between; min-height: 48px; padding: 0 16px; font-size: 14px; font-weight: 500; cursor: pointer; list-style: none; }
  [data-slot="template-outline-fold"] > summary::-webkit-details-marker { display: none; }
  [data-slot="template-outline-fold"] > summary::after { content: "+"; font-size: 18px; color: var(--k-muted); }
  [data-slot="template-outline-fold"][open] > summary::after { content: "–"; }
  [data-slot="template-outline-fold"] > summary:focus-visible { outline: 2px solid var(--k-focus, var(--k-hi)); outline-offset: 2px; border-radius: var(--k-radius); }
  [data-slot="template-outline-fold"] > [data-slot="template-outline-list"] { padding: 0 16px 12px; }
  @media print {
    [data-slot="template-outline"] { display: none !important; }
  }
}
